/**
 * Frappe Web Form Client Script
 *
 * This script triggers a PDF download automatically after a web form is submitted.
 * It calls a custom server-side API endpoint to generate the PDF for the newly
 * created document based on its 'exam_number'.
 *
 * How to use:
 * 1. In the Frappe Desk, navigate to and open your Web Form document.
 * 2. Scroll down to the "Scripting" section.
 * 3. Paste this entire code into the "Client Script" textarea.
 * 4. Ensure the fieldname 'exam_number' exists in your DocType and is included in the Web Form.
 * 5. Save the Web Form.
 */

frappe.web_form.after_save = () => {
    // This code block runs immediately after the web form is successfully saved.

    console.log("Web form successfully saved. Preparing PDF download...");

    // Retrieve the data from the document that was just created.
    const saved_doc = frappe.web_form.doc;

    // Check if the required 'exam_number' field has a value in the submitted data.
    if (saved_doc && saved_doc.exam_number) {
        const exam_number = saved_doc.exam_number;
        const doctype = frappe.web_form.doctype; // Get the doctype from the web form context.

        // Display a success message to the user.
        frappe.msgprint({
            title: __('Download Started'),
            indicator: 'green',
            message: __('Your PDF is being generated and will download automatically.')
        });

        // Construct the URL for your custom API endpoint.
        // This must match the path to your whitelisted Python function in your custom app.
        const apiUrl = '/api/method/telafer_university.api.student_pdf';

        // Use the URL API to safely build the final download URL with query parameters.
        const downloadUrl = new URL(window.location.origin + apiUrl);
        downloadUrl.searchParams.append('doctype', doctype);
        downloadUrl.searchParams.append('exam_number', exam_number);
        // You can add other optional parameters from your API function here if needed, for example:
        // downloadUrl.searchParams.append('format', 'My Custom Print Format');

        // Trigger the file download without navigating away from the page.
        // This is done by creating a temporary, invisible link and programmatically clicking it.
        try {
            const link = document.createElement('a');
            link.href = downloadUrl.toString();
            link.style.display = 'none'; // The link doesn't need to be visible.
            document.body.appendChild(link);
            link.click(); // Simulate a user clicking the link to start the download.
            document.body.removeChild(link); // Clean up by removing the temporary link.
        } catch (e) {
            console.error("PDF download failed.", e);
            frappe.msgprint({
                title: __('Download Error'),
                indicator: 'red',
                message: __('An error occurred while trying to download the PDF.')
            });
        }

    } else {
        // If the 'exam_number' is missing, log an error and inform the user.
        console.error("Could not find 'exam_number' in the saved document data:", saved_doc);
        frappe.msgprint({
            title: __('Download Failed'),
            indicator: 'red',
            message: __('Could not find the Exam Number in the submitted data. PDF cannot be generated.')
        });
    }
};
